取法宝类型 = function(名称)
	if 攻击法宝列表[名称] ~= nil then
		return 1
	elseif 防御法宝列表[名称] ~= nil then
		return 2
	elseif 辅助法宝列表[名称] ~= nil then
		return 3
	elseif 恢复法宝列表[名称] ~= nil then
		return 4
	elseif 诅咒法宝列表[名称] ~= nil then
		return 5
	end

	return nil
end

半数取整 = function(数值)
	数值 = tonumber(数值) + 0

	return math.floor(数值 + 0.5)
end

