列表打乱重组 = function(列表)
	local 列表0 = {}

	for n = 1, #列表 do
		列表0[n] = {
			名称 = 列表[n],
			排列 = ygsj(10000)
		}
	end

	table.sort(列表0, function (a, b)
		return b.排列 < a.排列
	end)

	local 列表1 = {}

	for i = 1, #列表0 do
		列表1[i] = 列表0[i].名称
	end

	return 列表1
end

无错误删除列表多个元素 = function(列表, 删除组)
	if type(删除组) ~= "table" or type(列表) ~= "table" or #删除组 < 1 or #列表 < 1 then
		return 列表
	end

	local 删除列表 = DeepCopy(删除组)

	if #删除列表 > 0 then
		table.sort(删除列表, function (a, b)
			return a < b
		end)

		local 已删 = 0

		for i = 1, #删除列表 do
			if 删除列表[i] - 已删 <= #列表 then
				table.remove(列表, 删除列表[i] - 已删)

				已删 = 已删 + 1
			end
		end
	end

	return 列表
end

