取等级标准 = function(id)
	local aa = math.min(取队伍平均等级(玩家数据[id].队伍, id), 玩家数据[id].角色.数据.等级)

	if 单机设置 then
		aa = 160
	end

	local bb = 1

	if 助战经验银子开关 and 奖励次数[id] > 1 then
		bb = 奖励次数[id] * 全局奖励倍率
	end

	local cc = 160

	if aa > 80 then
		cc = 180
	end

	return {
		qz1(aa),
		math.min(qz1(aa / cc * 1000) / 1000, 1),
		bb
	}
end

