时辰函数 = function()
	if 时辰信息.刷新 <= os.time() - 时辰信息.起始 then
		时辰信息.起始 = os.time()
		时辰信息.当前 = 时辰信息.当前 + 1

		if 时辰信息.当前 == 13 then
			时辰信息.当前 = 1
		end

		if 时辰信息.当前 == 5 then
			昼夜参数 = 2

			广播消息({
				频道 = "xt",
				内容 = "#Y天亮了...\n#G(物理伤害恢复正常了)"
			})
		elseif 时辰信息.当前 == 11 then
			昼夜参数 = 1

			广播消息({
				频道 = "xt",
				内容 = "#Y天黑了...\n#G(所有物理伤害降低20%)\n#G(夜战单位和地府不受影响)"
			})
		end

		天气间隔[1] = 天气间隔[1] + 1

		if 天气间隔[2] <= 天气间隔[1] then
			刷新天气()
		else
			for n, v in pairs(玩家数据) do
				if 玩家数据[n].管理 == nil then
					发送时辰天气(玩家数据[n].连接id, n)
				end
			end
		end
	end
end

