发送数据 = function(id, 序号, 内容, 封装)
	if id == nil then
		return
	end

	if 内容 == nil then
		内容 = "1"
	end

	if 封装 == nil then
		local 组合内容 = {
			序号 = 序号,
			内容 = 内容
		}

		__S服务:发送(服务端参数.网关id, id, table.tostring(组合内容))
	end

	组合内容 = {}
end

