	return os.date("%Y", 时间) .. "-" .. os.date("%m", 时间) .. "-" .. os.date("%d", 时间) .. " " .. os.date("%X", 时间)
end

时间转换2 = function(时间)
	return os.date("%Y", 时间) .. "/" .. os.date("%m", 时间) .. "/" .. os.date("%d", 时间) .. " " .. os.date("%H", 时间) .. ":" .. os.date("%M", 时间)
