保存玩家数据 = function()
	local 保存人数 = 0

	for n, v in pairs(玩家数据) do
		if 玩家数据[n].保存时间 == nil then
			玩家数据[n].保存时间 = os.time()
		end

		if 玩家数据[n] ~= nil and 玩家数据[n].管理 == nil and os.time() - 玩家数据[n].保存时间 >= 360 then
			玩家数据[n].保存时间 = os.time()

			__gge.safecall(玩家数据[n].角色.存档, 玩家数据[n].角色)

			保存人数 = 保存人数 + 1
		end
	end

	if 保存人数 > 0 then
		__S服务:输出("保存" .. 保存人数 .. "位玩家数据成功……")
	end

	if 异步保存次数 == nil then
		异步保存次数 = 0
	end

	异步保存次数 = 异步保存次数 + 1

	if 异步保存次数 >= 4 then
		异步保存次数 = 0

		__S服务:输出("清理内存完毕……")
		collectgarbage("collect")
	end
end

