取熟练度加成 = function(熟练度, 类别)
	if 类别 == "祝福" then
		return math.min(熟练度 / 10000, 10)
	elseif 类别 == "超级五行" then
		return math.min(熟练度 / 10000, 10)
	elseif 类别 == "特效" then
		return math.min(熟练度 / 10000, 10)
	elseif 类别 == "特技" then
		return math.min(熟练度 / 6666, 15)
	elseif 类别 == "双加" then
		return math.min(熟练度 / 4000, 40)
	elseif 类别 == "单加" then
		return math.min(熟练度 / 2000, 80)
	elseif 类别 == "保下限" then
		return math.min(熟练度 / 1000000, 0.8)
	end
end

