删除重复 = function(key)
	local k = nil

	for i = 1, #key do
		for j = i + 1, #key do
			if key[i] == key[j] then
				key[i] = -1
			end
		end
	end

	k = 1

	for i = 1, #key do
		if key[k] == -1 then
			table.remove(key, k)

			k = k - 1
		end

		k = k + 1
	end

	k = nil

	return key
end

