生成XY = function(x, y)
	local f = {
		x = tonumber(x) or 0,
		y = tonumber(y) or 0
	}

	setmetatable(f, {
		__add = function (a, b)
			return 生成XY(a.x + b.x, a.y + b.y)
		end,
		__sub = function (a, b)
			return 生成XY(a.x - b.x, a.y - b.y)
		end
	})

	return f
end

取两点距离 = function(src, dst)
	return math.sqrt(math.pow(src.x - dst.x, 2) + math.pow(src.y - dst.y, 2))
