取两点距离a = function(x, y, x1, y1)
	return math.sqrt(math.pow(x - x1, 2) + math.pow(y - y1, 2))
end

取距离坐标 = function(xy, r, a)
	local x1 = 0
	local y1 = 0
	x1 = r * math.cos(a) + xy.x + 取随机数(-2, 2)
	y1 = r * math.sin(a) + xy.y + 取随机数(-2, 2)

	return 生成XY(math.floor(x1), math.floor(y1))
end

