取超级五行处理 = function(装备等级, 概率, 熟练度, 定制)
	熟练度 = (熟练度 or 0) + 0
	local 超级五行 = {}

	if 取随机数(1, 10000) <= (概率 + 取熟练度加成(熟练度, "超级五行")) * 100 or 定制 ~= nil then
		local 五行随机 = ygsj()

		if 定制 ~= nil and 超级五行选择1[定制.超级五行] ~= nil then
			五行随机 = 超级五行选择1[定制.超级五行] * 20
		end

		if 五行随机 <= 20 then
			超级五行.类型 = "金"
			超级五行.属性 = "伤害"
			超级五行.数值 = 装备等级 * 0.8
		elseif 五行随机 <= 40 then
			超级五行.类型 = "木"
			超级五行.属性 = "治疗能力"
			超级五行.数值 = 装备等级 * 0.8
		elseif 五行随机 <= 60 then
			超级五行.类型 = "水"
			超级五行.属性 = "速度"
			超级五行.数值 = 装备等级 * 0.6
		elseif 五行随机 <= 80 then
			超级五行.类型 = "火"
			超级五行.属性 = "灵力"
			超级五行.数值 = 装备等级 * 0.6
		else
			超级五行.类型 = "土"
			超级五行.属性 = "防御"
			超级五行.数值 = 装备等级 * 1.2
		end
	end

	return 超级五行
end

取多项数字列表 = function(起, 终, 个数)
	local lb = {}
	local aa = 终 - 起 + 1

	for i = 1, aa do
		lb[i] = 起 + i - 1
	end

	if 个数 <= aa then
		local bb = aa - 个数

		for i = 1, bb do
			table.remove(lb, ygsj(#lb))
		end

		return lb
	else
		return lb
	end
end

取列表多项 = function(列表, 数量, 起始)
	if 起始 == nil then
		起始 = 1
	end

	local 列表1 = 列表2加入到列表1({}, 列表)
	local jg = {}

	for i = 1, 数量 do
		if 起始 <= #列表1 then
			local n = 取随机数(起始, #列表1)
			jg[#jg + 1] = 列表1[n]

			table.remove(列表1, n)
		end
	end

	return jg
end

