设置任务bb = function(id, 任务id)
	local 等级 = 玩家数据[id].角色.数据.等级
	local 临时等级 = 等级 - 10

	if 临时等级 > 85 then
		临时等级 = 85
	end

	local 临时等级1 = 等级 - 50

	if 临时等级1 < 1 then
		临时等级1 = 1
	end

	local 类型 = 取等级怪(取随机数(临时等级1, 临时等级))
