取飞升条件 = function(id)
	if 玩家数据[id].角色.数据.等级 < 135 then
		return false
	end

	local 满足条件 = 0

	for i = 1, #玩家数据[id].角色.数据.师门技能 do
		if 玩家数据[id].角色.数据.师门技能[i].等级 >= 130 then
			满足条件 = 满足条件 + 1
		end
	end

	if 满足条件 < 6 then
		return false
	end

	return true
end

