取低级要诀 = function(数量)
	if 数量 == nil or 数量 <= 1 then
		return 低级兽决[ygsj(#低级兽决)]
	else
		local 避免 = {
			"隐身",
			"冲击",
			"恐吓",
			"恐怖",
			"神佑复生"
		}
		local ms = {}

		for i = 1, #低级兽决 do
			if 取列表中是否存在内容(避免, 低级兽决[i]) == false then
				ms[#ms + 1] = 低级兽决[i]
			end
		end

		local ms1 = {}

		for i = 1, 数量 do
			local n = ygsj(#ms)
			ms1[i] = ms[n]

			table.remove(ms, n)
		end

		return ms1
	end
end

