判断n号帮 = function(id, 编号)
	local id组 = {}

	if 玩家数据[id].队伍 == 0 then
		id组[1] = id
	else
		local 队伍id = 玩家数据[id].队伍

		for n = 1, #队伍数据[队伍id].成员数据 do
			id组[n] = 队伍数据[队伍id].成员数据[n]
		end
	end

	for n = 1, #id组 do
		if 玩家数据[id组[n]].角色.数据.帮派数据.编号 ~= 编号 then
			return false
		end
	end

	return true
end

