保留小数位数 = function(nNum, n)
	if type(nNum) ~= "number" then
		return nNum
	end

	n = n or 0
	n = math.floor(n)
	local fmt = "%." .. n .. "f"
	local nRet = tonumber(string.format(fmt, nNum))

	return nRet
end

随机排序 = function(tbl)
	local n = #tbl

	for i = 1, n do
		local j = math.random(i, n)

		if i < j then
			tbl[i], tbl[j] = tbl[j], tbl[i]
		end
	end
end

铃铛奖励生成 = function(玩家id, 名称, 数量)
	local 铃铛奖励数据 = nil
	local 识别码 = 玩家id .. "_" .. os.time() .. "_" .. 取随机数(1000, 9999999) .. "_" .. 随机序列
	随机序列 = 随机序列 + 1
	铃铛奖励数据 = 物品类()

	铃铛奖励数据:置对象(名称)

	临时道具 = 取物品数据(名称)
	临时道具.总类 = 临时道具[2]
	临时道具.子类 = 临时道具[4]
	临时道具.分类 = 临时道具[3]
	铃铛奖励数据.数量 = 1

	if 名称 == "点化石" then
		if ygsj(100) <= 1 then
			铃铛奖励数据.附带技能 = "剑荡四方"
		elseif ygsj(100) <= 5 then
			铃铛奖励数据.附带技能 = 取高级要诀()
		else
			铃铛奖励数据.附带技能 = 取低级要诀()
		end
	elseif 名称 ~= "藏宝图" then
		if 名称 == "高级藏宝图" then
		elseif 名称 == "神兜兜" then
			铃铛奖励数据.数量 = 数量
		elseif 名称 == "珍珠" then
			铃铛奖励数据.级别限制 = 数量
		elseif 名称 == "清灵净瓶" then
			铃铛奖励数据.数量 = 数量
		elseif 名称 == "魔兽要诀" then
		elseif 名称 == "高级魔兽要诀" then
		elseif 名称 == "召唤兽内丹" then
		elseif 名称 == "百炼精铁" then
			铃铛奖励数据.子类 = 数量
		elseif 名称 == "金柳露" then
			铃铛奖励数据.数量 = 数量
		elseif 名称 == "超级金柳露" then
			铃铛奖励数据.数量 = 数量
		elseif 名称 == "九转金丹" then
			铃铛奖励数据.阶品 = 数量
		end
	end

	if 铃铛奖励数据.可叠加 then
		铃铛奖励数据.数量 = 数量
	end

	铃铛奖励数据.识别码 = 识别码

	return 铃铛奖励数据
end

取唯一任务 = function(类型, id)
	随机序列 = 随机序列 + 1

	if id ~= nil then
		local bm = id .. "_" .. 类型 .. "_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)

		if 玩家数据[id].队伍 == 0 then
			return bm, {
				id
			}
		else
			local fh = {}

			for i = 1, #队伍数据[玩家数据[id].队伍].成员数据 do
				if 队伍数据[玩家数据[id].队伍].成员数据[i] ~= nil then
					fh[#fh + 1] = 队伍数据[玩家数据[id].队伍].成员数据[i]
				end
			end

			return bm, fh
		end
	end

	return "_" .. 类型 .. "_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)
end

取个人唯一任务 = function(类型, id)
