取地煞门派 = function(角色)
	local 门派列表 = {
		人男 = {
			"大唐官府",
			"方寸山",
			"化生寺",
			"神木林"
		},
		人女 = {
			"大唐官府",
			"方寸山",
			"女儿村",
			"神木林"
		},
		魔男 = {
			"魔王寨",
			"阴曹地府",
			"无底洞",
			"狮驼岭"
		},
		魔女 = {
			"魔王寨",
			"阴曹地府",
			"无底洞",
			"盘丝岭"
		},
		仙男 = {
			"龙宫",
			"天宫",
			"凌波城",
			"五庄观"
		},
		仙女 = {
			"龙宫",
			"天宫",
			"凌波城",
			"普陀山"
		}
	}
	local 门派 = ""

	if 角色 == "剑侠客" or 角色 == "逍遥生" or 角色 == "偃无师" then
		门派 = 门派列表.人男[ygsj(4)]
	elseif 角色 == "巫蛮儿" or 角色 == "飞燕女" or 角色 == "英女侠" then
		门派 = 门派列表.人女[ygsj(4)]
	elseif 角色 == "巨魔王" or 角色 == "虎头怪" or 角色 == "杀破狼" then
		门派 = 门派列表.魔男[ygsj(4)]
	elseif 角色 == "狐美人" or 角色 == "骨精灵" or 角色 == "鬼潇潇" then
		门派 = 门派列表.魔女[ygsj(4)]
	elseif 角色 == "神天兵" or 角色 == "龙太子" or 角色 == "羽灵神" then
		门派 = 门派列表.仙男[ygsj(4)]
	elseif 角色 == "玄彩娥" or 角色 == "舞天姬" or 角色 == "桃夭夭" then
		门派 = 门派列表.仙女[ygsj(4)]
	end

	return 门派
end

取门派类型 = function(门派)
	local 封印 = {
		五庄观 = 1,
		方寸山 = 1,
		盘丝岭 = 1,
		女儿村 = 1
	}
	local 辅助 = {
		普陀山 = 1,
		神木林 = 1,
		化生寺 = 1,
		阴曹地府 = 1,
		无底洞 = 1
	}
	local 物理 = {
		大唐官府 = 1,
		五庄观 = 1,
		狮驼岭 = 1,
		凌波城 = 1,
		阴曹地府 = 1,
		天宫 = 1
	}
	local 法术 = {
		魔王寨 = 1,
		女儿村 = 1,
		龙宫 = 1,
		神木林 = 1,
		天宫 = 1
	}
	local 类型 = {}

	if 封印[门派] ~= nil then
		类型[#类型 + 1] = "封印"
	end

	if 辅助[门派] ~= nil then
		类型[#类型 + 1] = "辅助"
	end

	if 物理[门派] ~= nil then
		类型[#类型 + 1] = "物理"
	end

	if 法术[门派] ~= nil then
		类型[#类型 + 1] = "法术"
	end

	return 类型[ygsj(#类型)]
end

