取护符等级 = function(名称)
	for i = 1, #重置丹列表 do
		if 名称 == 重置丹列表[i] then
			return i
		end
	end

	for i = 1, #通灵装备 do
		if 名称 == 通灵装备[i] then
			return i
		end
	end

	return nil
end

取护符技能 = function(名称, 技能个数)
	local 数量 = 1

	if ygsj(1000) <= 通灵装备双技能概率 then
		数量 = 2
	end

	if 技能个数 ~= nil then
		数量 = qz(技能个数 or 数量)
	end

	local 技能列表 = {}
	local 高级 = {}
	local 高级1 = {
		"须弥真言",
		"灵能激发",
		"风起龙游",
		"灵山禅语",
		"浮云神马",
		"神出鬼没",
		"昼伏夜出",
		"千钧一怒",
		"灵山禅语",
		"诸天正法",
		"津津有味",
		"烈焰斩",
		"影袭",
		"理直气壮",
		"战斗号角",
		"生命守护",
		"上善若水",
		"驱怪",
		"龙魂",
		"溜之大吉"
	}
	local 低级 = {
		"奔雷咒",
		"泰山压顶",
		"水漫金山",
		"地狱烈火",
		"剑气四射",
		"奔雷咒"
	}
	local wz = nil

	for i = 1, #高级兽决 do
		高级[#高级 + 1] = 高级兽决[i]
	end

	for i = 1, #低级兽决 do
		低级[#低级 + 1] = 低级兽决[i]
	end

	for i = 1, 数量 do
		if i == 1 and 名称 ~= "通灵神臂" then
			wz = ygsj(#高级)
			技能列表[#技能列表 + 1] = 高级[wz]
		elseif i == 1 and 名称 == "通灵神臂" then
			wz = ygsj(#低级兽决)
			技能列表[#技能列表 + 1] = 低级兽决[wz]
		elseif 名称 == "通灵神戒" then
			local pd = 1
			技能列表[#技能列表 + 1] = ""

			while 技能列表[#技能列表] == 技能列表[1] or pd == 1 do
				if ygsj(1000) <= 通灵装备特殊技能概率 and #高级1 > 0 then
					wz = ygsj(#高级1)
					技能列表[#技能列表] = 高级1[wz]

					table.remove(高级1, wz)
				else
					wz = ygsj(#高级)
					技能列表[#技能列表] = 高级[wz]

					table.remove(高级, wz)
				end

				pd = 0
			end
		elseif 名称 == "通灵神符" or 名称 == "通灵神臂" then
			local pd = 1
			技能列表[#技能列表 + 1] = ""

			while 技能列表[#技能列表] == 技能列表[1] or pd == 1 do
				wz = ygsj(#低级)
				技能列表[#技能列表] = 低级[wz]

				table.remove(低级, wz)

				pd = 0
			end
		end
	end

	return 技能列表
end

