初始化交易中心 = function()
	local 低级装备 = {}

	for i = 1, 6 do
		local aa = 交易中心配置1[交易中心配置[i]]

		if aa == 1 or aa == "1" then
			table.insert(低级装备, {
				类型 = 交易中心标签[1][i],
				内容 = 取制造指南书组(40 + i * 10)
			})
		end
	end

	table.insert(交易中心, 低级装备)

	local 高级装备 = {}

	for i = 7, 12 do
		local aa = 交易中心配置1[交易中心配置[i]]

		if aa == 1 or aa == "1" then
			table.insert(高级装备, {
				类型 = 交易中心标签[2][i - 6],
				内容 = 取制造指南书组(40 + i * 10)
			})
		end
	end

	table.insert(交易中心, 高级装备)

	local 宠物相关 = {}
	local bb = {
		取低级魔兽要诀组,
		取高级魔兽要诀组,
		取特殊魔兽要诀组,
		取交易中心道具组,
		取低级灵饰书组,
		取高级灵饰书组
	}

	for i = 13, 18 do
		local aa = 交易中心配置1[交易中心配置[i]]

		if aa == 1 or aa == "1" then
			table.insert(宠物相关, {
				类型 = 交易中心标签[3][i - 12],
				内容 = bb[i - 12]()
			})
		end
	end

	table.insert(交易中心, 宠物相关)

	local 野怪相关 = {}
	local bb = {
		{
			0,
			35
		},
		{
			45,
			75
		},
		{
			85,
			115
		},
		{
			125,
			155
		},
		{
			156,
			175
		},
		{
			190,
			190,
			true
		}
	}

	for i = 19, 24 do
		local aa = 交易中心配置1[交易中心配置[i]]

		if aa == 1 or aa == "1" then
			table.insert(野怪相关, {
				类型 = 交易中心标签[4][i - 18],
				内容 = 取交易中心野怪组(bb[i - 18][1], bb[i - 18][2], bb[i - 18][3])
			})
		end
	end

	table.insert(交易中心, 野怪相关)

	local 道具相关 = {}

	table.insert(交易中心, 道具相关)
	写出文件("tysj/交易中心.txt", table.tostring(交易中心))
	__S服务:输出("初始化交易中心成功")
end

更新交易中心涨跌幅 = function()
	for i = 1, #交易中心 do
		for n = 1, #交易中心[i] do
			for k = 1, #交易中心[i][n].内容 do
				交易中心[i][n].内容[k].日涨跌幅 = 0
			end
		end
	end

	写出文件("tysj/交易中心.txt", table.tostring(交易中心))
	__S服务:输出("交易中心日涨跌幅更新成功")
end

