取灵饰书组 = function(等级)
	local 制造指南书数组 = {}
	local 初始价格 = 100000

	if 等级 <= 80 then
		初始价格 = 等级 * 25000
	elseif 等级 <= 100 then
		初始价格 = 等级 * 50000
	elseif 等级 <= 120 then
		初始价格 = 等级 * 100000
	elseif 等级 <= 140 then
		初始价格 = 等级 * 200000
	elseif 等级 <= 160 then
		初始价格 = 等级 * 400000
	end

	local 铁数据 = {
		日涨跌幅 = 0,
		参数一类型 = "子类",
		名称 = "元灵晶石",
		参数一 = 等级,
		价格 = math.floor(初始价格 / 2)
	}
	铁数据.最低价格 = qz(铁数据.价格 / 10)

	table.insert(制造指南书数组, 铁数据)

	local 灵饰特效1 = {
		"耳饰",
		"佩饰",
		"戒指",
		"手镯"
	}

	for i = 1, 4 do
		local 临时指南 = {
			参数一类型 = "子类",
			名称 = "灵饰指南书",
			参数二类型 = "特效",
			日涨跌幅 = 0,
			参数一 = 等级,
			参数二 = 灵饰特效1[i],
			价格 = 初始价格
		}
		临时指南.最低价格 = qz(临时指南.价格 / 10)

		table.insert(制造指南书数组, 临时指南)
	end

	return 制造指南书数组
end

取制造指南书组 = function(等级)
	local 制造指南书数组 = {}
	local 初始价格 = 100000

	if 等级 <= 50 then
		初始价格 = 等级 * 8000
	elseif 等级 <= 80 then
		初始价格 = 等级 * 12000
	elseif 等级 <= 100 then
		初始价格 = 等级 * 25000
	elseif 等级 <= 120 then
		初始价格 = 等级 * 50000
	elseif 等级 <= 170 then
		初始价格 = 等级 * 100000
	end

	local 铁数据 = {
		日涨跌幅 = 0,
		参数一类型 = "子类",
		名称 = "百炼精铁",
		参数一 = 等级,
		价格 = math.floor(初始价格 / 2)
	}
	铁数据.最低价格 = qz(铁数据.价格 / 10)

	table.insert(制造指南书数组, 铁数据)

	for i = 1, 25 do
		local 临时指南 = {
			参数一类型 = "子类",
			名称 = "制造指南书",
			参数二类型 = "特效",
			日涨跌幅 = 0,
			参数一 = 等级,
			参数二 = i,
			价格 = 初始价格
		}
		临时指南.最低价格 = qz(临时指南.价格 / 10)

		table.insert(制造指南书数组, 临时指南)
	end

	return 制造指南书数组
end

