	local 类型 = 取等级怪1(等级1, 等级2)
	local 野怪名称, 临时兽决 = nil

	for i = 1, #类型 do
		野怪名称 = 取敌人信息(类型[i])
		类型[i] = 野怪名称[2]
		local 等级 = 野怪名称[3]
		临时兽决 = {
			参数一 = "野怪",
			参数一类型 = "召唤兽",
