数组去重 = function(a)
	local b = {}

	for k, v in ipairs(a) do
		if #b == 0 then
			b[1] = v
		else
			local index = 0

			for i = 1, #b do
				if v == b[i] then
					break
				end

				index = index + 1
			end

			if index == #b then
				b[#b + 1] = v
			end
		end
	end

	return b
end

数字转简 = function(数字)
	if 数字 == nil then
		return ""
	end

	local a = tonumber(数字) + 0
	local b, c = nil
	local d = ""

	if a >= 1000000000000.0 then
		b = a / 1000000000000.0
		c = 保留小数位数(b, 2)
		d = tostring(c) .. "万亿"
	elseif a >= 100000000 then
		b = a / 100000000
		c = 保留小数位数(b, 4)
		d = tostring(c) .. "亿"
	elseif a >= 10000 then
		b = a / 10000
		c = 保留小数位数(b, 2)
		d = tostring(c) .. "万"
	else
		d = tostring(a)
	end

	return d
end

