取洗宠技能 = function(模型, 变异, 自带技能列表, 超级金柳露)
	local jn = 自带技能列表
	local jn0 = {}
	local jn1 = 取天生(去模型进阶(模型))
	local cj = 0

	if 超级金柳露 ~= nil then
		cj = 5
	end

	for q = 1, #jn do
		if ygsj() - cj <= (洗宠特殊技能概率[jn[q]] or 洗宠技能概率) then
			table.insert(jn0, jn[q])
		end
	end

	for i = 1, #jn1 do
		table.insert(jn0, jn1[i])
	end

	if 变异 == true and ygsj() - cj <= 变异多技能概率 then
		local jnlb = 列表模式转换(jn0)
		local aa = ""

		while true do
			aa = 取低级要诀()

			if jnlb[aa] == nil then
				break
			end
		end

		table.insert(jn0, aa)
	end

	jn0 = 删除重复(jn0)

	return jn0
end

